              "paragraphs": [
                "The textbook connects the Haudenosaunee term kanakerahsera with naker, meaning “to be born.” It also traces the English word nation to a Latin word associated with birth. These examples connect the idea of nation to belonging and family. They are examples of language and meaning, rather than a single definition that every Nation must use.",
                "In everyday conversation, people often means several persons. In the phrase “a people,” it can mean a collective with a shared identity. That distinction helps us understand the Dene Declaration: its authors are asserting rights for the Dene Nation as a whole.",
                "The term Indigenous peoples also carries a relationship to place and history. The textbook contrasts peoples whose histories and cultures originate in a place with people who migrate there. Identity is not something we can decide by appearance. Its discussion of language asks us to consider what is at stake when a people’s language is endangered in its own homeland."
              ]
