              "creator": "Contemporary Issues textbook authors, quoting the Treaty Eight commissioners’ report",
              "extract": "“There is no immediate necessity for the general laying out of reserves or the allotting of land,” the treaty commissioners wrote in their report. “It will be quite time enough to do this as advancing settlement makes necessary the surveying of the land.”",
