              "creator": "Harold Cardinal, The Unjust Society (1969), as excerpted in the textbook",
              "extract": "To the Indians of Canada, the treaties represent an Indian Magna Carta. The treaties are important to us, because we entered into these negotiations with faith, with hope for a better life with honour.",
