              "response": "Archibald spoke a hunting, fishing, and trapping commitment across traditional territories, then left it out of the written Treaty One text (Source A, p. 29). Leaders later argued this pattern generally — negotiated promises not always reflected in signed documents (Source H, p. 31) — while the record shows dated repairs: left-out groups added by adhesion into the 1950s (Source G), plus revised annuities and implements after argument (p. 31). The three questions stay separate: the commitment is evidenced by the council account, the gap by the document’s own silence, and implementation by dated repairs. What the trail cannot show is any single family’s experience — the evidence proves the structure of the gap, not its weight on any one life.",
