              "title": "Source P",
              "extract": "• Aboriginal self-governments should operate within the framework of the Canadian constitution, and self-government powers should be harmonious with other levels of government under the constitution. • Provincial and territorial governments must be part of negotiations for self-government because some of the powers under negotiation may affect provincial and territorial areas of jurisdiction. • Aboriginal self-government does not mean sovereignty in an international sense, but rather an enhancement of Aboriginal peoples’ participation in the Canadian federal system. • The Canadian Charter of Rights and Freedoms will bind Aboriginal governments.",
