              "title": "Source V",
              "extract": "The requirement to have implementation plans ensures that self-government agreements cannot be concluded without agreement upon crucial issues, such as time frames and financial contributions. The goal of implementation plans is to have fewer misunderstandings between partners once an agreement is reached.",
              "sourceType": "Textbook narration",
              "locator": "Chapter 3, printed p. 102 (supplied PDF p. 110)",
              "attribution": "Contemporary Issues: Aboriginal Studies 30 (Les Éditions Duval, 2005)",
              "creator": "Contemporary Issues textbook authors",
